<?php
namespace App\Http\Controllers;
use App\Models\{Event,Contributor,EventContribution,AppSetting}; use Illuminate\Http\Request; use Barryvdh\DomPDF\Facade\Pdf;
class CollectionController extends Controller { public function show(Event $event){$event->load('contributions.contributor');$available=Contributor::where('status',true)->whereNotIn('id',$event->contributions->pluck('contributor_id'))->orderBy('name')->get();return view('collections.show',compact('event','available'));} public function setPerHead(Request $r,Event $event){$data=$r->validate(['per_head_amount'=>'nullable|numeric|min:0']);$event->update($data);if($event->per_head_amount !== null){$event->contributions()->where('amount_due',0)->update(['amount_due'=>$event->per_head_amount]);}return response()->json(['ok'=>true,'per_head_amount'=>$event->per_head_amount]);} public function add(Request $r,Event $event){$data=$r->validate(['contributor_id'=>'required|exists:contributors,id']);$contributor=Contributor::whereKey($data['contributor_id'])->where('status',true)->firstOrFail();$row=EventContribution::firstOrCreate(['event_id'=>$event->id,'contributor_id'=>$contributor->id],['amount_due'=>$event->per_head_amount ?? 0,'amount_paid'=>0,'payment_status'=>'not_paid']);return response()->json(['ok'=>true,'row'=>$this->row($row->fresh('contributor')),'totals'=>$this->totals($event)]);} public function payment(Request $r,Event $event,EventContribution $contribution){abort_unless($contribution->event_id===$event->id,404);$data=$r->validate(['amount_paid'=>'required|numeric|min:0','notes'=>'nullable']);$contribution->fill($data);$contribution->refreshPaymentStatus();$contribution->save();return response()->json(['ok'=>true,'row'=>$this->row($contribution->fresh('contributor')),'totals'=>$this->totals($event)]);} public function remove(Event $event,EventContribution $contribution){abort_unless($contribution->event_id===$event->id,404);if((float)$contribution->amount_paid>0)return response()->json(['message'=>'Paid contributions are retained for history.'],422);$contribution->delete();return response()->json(['ok'=>true,'totals'=>$this->totals($event)]);} public function pdf(Event $event){$event->load('contributions.contributor');$brandName=AppSetting::value('site_name','Festiva');return Pdf::loadView('pdf.collection',['event'=>$event,'totals'=>$this->totals($event),'brandName'=>$brandName])->setPaper('a4')->stream('collection-'.$event->id.'.pdf');} private function totals(Event $event){$rows=$event->contributions()->get();$expected=$rows->sum('amount_due');$collected=$rows->sum('amount_paid');return ['expected'=>(float)$expected,'collected'=>(float)$collected,'outstanding'=>(float)$expected-(float)$collected,'paid'=>$rows->where('payment_status','paid')->count(),'partial'=>$rows->where('payment_status','partial')->count(),'not_paid'=>$rows->where('payment_status','not_paid')->count()];} private function row(EventContribution $row){return ['id'=>$row->id,'name'=>$row->contributor->name,'email'=>$row->contributor->email,'phone'=>$row->contributor->phone,'active'=>$row->contributor->status,'due'=>(float)$row->amount_due,'paid'=>(float)$row->amount_paid,'status'=>$row->payment_status,'paid_at'=>optional($row->paid_at)->format('d M Y'),'notes'=>$row->notes];} }
